  "https://www.rent.com/massachusetts/somerville-apartments/1-bedroom-under-3000"
];

const allCandidates = [];
const seenUrls = new Set();

for (const url of urlsToFetch) {
  console.log(`Navigating to ${url}...`);
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

